}
Bool bfmeSphereOverlap(const BfmeCollisionShape *first,
	const BfmeCollisionShape *second);

static __forceinline Bool bfmeOverlap(BfmeObjF0 &thisObject, BfmeObjF0 &thatObject, Bool cur)
{
	switch (thisObject.m_type)
	{
		case GEOMETRY_BOX:
			if (thatObject.m_type == GEOMETRY_BOX)
				return BfmeObjF0::bfmeIntersectsBoxes(&thisObject, &thatObject);
			return BfmeObjF0::bfmeIntersectsBox(&thatObject, &thisObject);
		case GEOMETRY_SPHERE:
		case GEOMETRY_CYLINDER:
			if (thatObject.m_type == GEOMETRY_BOX)
				return BfmeObjF0::bfmeIntersectsBox(&thisObject, &thatObject);
			return bfmeSphereOverlap(reinterpret_cast<const BfmeCollisionShape *>(&thisObject), reinterpret_cast<const BfmeCollisionShape *>(&thatObject));
	}
	return cur;
}

__declspec(noinline) Bool GeometryInfo::bfmeIntersects(const Coord3D &thisPosition,
	Real thisAngle, const GeometryInfo &otherGeometry,
	const Coord3D &otherPosition, Real otherAngle) const
{
	Bool result = false;
	for (const BfmeShapeF0 *thisShape = (const BfmeShapeF0 *)begin;
		thisShape != (const BfmeShapeF0 *)end; ++thisShape)
	{
		if (!thisShape->m_enabled)
			continue;
		if (result)
			break;

		BfmePosF0 thisCenter;
		bfmeTransformShape(&thisCenter, &thisPosition, thisShape, thisAngle);

		for (const BfmeShapeF0 *thatShape = (const BfmeShapeF0 *)otherGeometry.begin;
			thatShape != (const BfmeShapeF0 *)otherGeometry.end; ++thatShape)
		{
			if (!thatShape->m_enabled)
				continue;
			if (result)
				break;

			BfmePosF0 thatCenter;
			bfmeTransformShape(&thatCenter, &otherPosition, thatShape,
				otherAngle);

			Real thisHeight = 0.0f;
			switch (thisShape->m_type)
			{
				case GEOMETRY_SPHERE:
					thisHeight = thisShape->m_majorRadius;
					break;
				case GEOMETRY_CYLINDER:
				case GEOMETRY_BOX:
					thisHeight = thisShape->m_height;
					break;
			}
			thisHeight += thisShape->m_offsetZ;
			thisHeight += thisCenter.z;
			if (otherPosition.z > thisHeight)
				continue;

			Real thatHeight = 0.0f;
			switch (thatShape->m_type)
			{
				case GEOMETRY_SPHERE:
					thatHeight = thatShape->m_majorRadius;
					break;
				case GEOMETRY_CYLINDER:
				case GEOMETRY_BOX:
					thatHeight = thatShape->m_height;
					break;
			}
			thatHeight += thatShape->m_offsetZ;
			thatHeight += thatCenter.z;
			if (thisCenter.z > thatHeight)
				continue;

			BfmeObjF0 thisObject;
			BfmeObjF0 thatObject;
			thisObject.set(&thisCenter, thisShape, thisAngle);
			thatObject.set(&thatCenter, thatShape, otherAngle);

			result = bfmeOverlap(thisObject, thatObject, result);
		}
	}
	return result;
}

struct ContactPoint : Coord3D { ContactPoint(const Coord3D &r) { x = r.x; y = r.y; z = r.z; } };
static inline void contactCopy(Coord3D &out, const Coord3D &in) { out = in; }

Bool GeometryInfo::getBestContactPoint(Coord3D *out, const Coord3D *caller, const char *label, Int preference, Int seed, Bool ignoreCollision) const
{
	if (g_bfmeDockingTraceActive && caller && TheCRCParameterCheck)
		bfmeRetailCritterDesyncLog(TheCRCParameterCheck, "        GeometryInfo::getBestContactPoint, callerPos=%g,%g,%g, label=%s, pref=%d, seed=%d, skipCollideTest=%d, m_innermostContactPoint=%g,%g,%g", caller->x, caller->y, caller->z, label ? label : "NONE", preference, seed, ignoreCollision ? "TRUE" : "FALSE", defaultPosition.x, defaultPosition.y, defaultPosition.z);
	contactCopy(*out, defaultPosition);
	switch (preference) {
	case 3: {
		int count = (int)contacts.size();
		if (count >= 2) {
			int index = seed % (count - 1);
			ContactPoint first = contacts[index].position;
			ContactPoint second = contacts[index + 1].position;
			float t = (float)((seed >> 8) & 255); t *= (1.0f / 255.0f);
			first.x *= t; first.y *= t; first.z *= t;
			float inverse = 1.0f - t; second.x *= inverse; second.y *= inverse; second.z *= inverse;
			first.x += second.x; first.y += second.y; first.z += second.z;
			contactCopy(*out, first);
		}
		if (out->z > getMaxHeightAbovePosition()) out->z = getMaxHeightAbovePosition();
		if (!ignoreCollision && !bfmeIntersects(g_rva0130E908Origin, 0.0f, *(const GeometryInfo *)&g_bfmeStaticAAO, *out, 0.0f)) {
			for (GeometryShape *shape = begin; shape != end; ++shape) {
				if (!shape->enabled) continue;
				out->x = shape->offset.x; out->y = shape->offset.y; break;
			}
		}
		if (out->z > getMaxHeightAbovePosition()) { out->z = getMaxHeightAbovePosition(); }
		else if (out->z < getMaxHeightAbovePosition() * 0.1f) out->z = getMaxHeightAbovePosition() * 0.1f;
		return true;
	}
	case 1:
		contactCopy(*out, preferredPosition);
		if (out->z > getMaxHeightAbovePosition()) out->z = getMaxHeightAbovePosition();
		return true;
	case 0: {
		if (caller) {
			int count = (int)contacts.size();
			int best = count; float bestDistance = 3.402823466e+38f;
			for (int i = 0; i < count; ++i) {
				const GeometryContactRecord *geometryContactRecord;
				if (label) { const AsciiString &asciiString = contacts[i].label; geometryContactRecord = &contacts[i]; if (asciiString.compare(label) != 0) continue; }
				else { const AsciiString &asciiString = contacts[i].label; geometryContactRecord = &contacts[i]; if (asciiString.compare("") != 0) continue; }
				Coord3D pos = geometryContactRecord->position;
				if (pos.z > getMaxHeightAbovePosition()) pos.z = getMaxHeightAbovePosition();
				if (!ignoreCollision && !bfmeIntersects(g_rva0130E908Origin, 0.0f, *(const GeometryInfo *)&g_bfmeStaticAAO, pos, 0.0f)) continue;
				float dx = pos.x - caller->x, dy = pos.y - caller->y, dz = pos.z - caller->z;
				float d = dz * dz + (dx * dx + dy * dy);
				if (d < bestDistance) { bestDistance = d; best = i; }
			}
			if (best != count) {
				contactCopy(*out, contacts[best].position);
				if (out->z > getMaxHeightAbovePosition()) { out->z = getMaxHeightAbovePosition(); }
				else if (out->z < getMaxHeightAbovePosition() * 0.1f) out->z = getMaxHeightAbovePosition() * 0.1f;
				return true;
			}
		}
		break;
	}
	default: break;
	}
	return false;
}
